def encode(value) -> str:
    if value is True:
        text = "true"
    elif value is False:
        text = "false"
    else:
        text = str(value)
    # quote() leaves only unreserved characters (letters, digits, "-._~")
    # unescaped when safe="", encodes as UTF-8, and uses uppercase hex.
    return quote(text, safe="")

